Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnslancarestoqueUEitemWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'LANESTITEMLOCDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &lanestItemLocDescricao1.FromString(&GridStateDynamicFilter.Value) If not &lanestItemLocDescricao1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Unidade", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Unidade", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&lanestItemLocDescricao1) EndIf Case &DynamicFiltersSelector1 = !'LANESTITEMPRODDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &lanestItemProdDescricao1.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdDescricao1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&lanestItemProdDescricao1) EndIf Case &DynamicFiltersSelector1 = !'LANESTITEMPRODCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &lanestItemProdCodigo1.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdCodigo1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Codigo", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &lanestItemProdCodigo1 EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'LANESTITEMLOCDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &lanestItemLocDescricao2.FromString(&GridStateDynamicFilter.Value) If not &lanestItemLocDescricao2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Unidade", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Unidade", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&lanestItemLocDescricao2) EndIf Case &DynamicFiltersSelector2 = !'LANESTITEMPRODDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &lanestItemProdDescricao2.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdDescricao2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&lanestItemProdDescricao2) EndIf Case &DynamicFiltersSelector2 = !'LANESTITEMPRODCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &lanestItemProdCodigo2.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdCodigo2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Codigo", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &lanestItemProdCodigo2 EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'LANESTITEMLOCDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &lanestItemLocDescricao3.FromString(&GridStateDynamicFilter.Value) If not &lanestItemLocDescricao3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Unidade", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Unidade", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&lanestItemLocDescricao3) EndIf Case &DynamicFiltersSelector3 = !'LANESTITEMPRODDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &lanestItemProdDescricao3.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdDescricao3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&lanestItemProdDescricao3) EndIf Case &DynamicFiltersSelector3 = !'LANESTITEMPRODCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &lanestItemProdCodigo3.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdCodigo3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Codigo", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &lanestItemProdCodigo3 EndIf EndCase EndIf EndIf EndIf If not (&TFlanestItemProdCodigo.IsEmpty() AND &TFlanestItemProdCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Codigo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFlanestItemProdCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFlanestItemProdCodigo_To EndIf If not (&TFlanestItemProdDescricao_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Descrição") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFlanestItemProdDescricao_Sel) Else If not (&TFlanestItemProdDescricao.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Descrição") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFlanestItemProdDescricao) EndIf EndIf If not (&TFlanestItemProdUni.IsEmpty() AND &TFlanestItemProdUni_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Unidade") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFlanestItemProdUni WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFlanestItemProdUni_To EndIf If not (&TFlanestItemQuantidade.IsEmpty() AND &TFlanestItemQuantidade_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Quantidade") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFlanestItemQuantidade WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFlanestItemQuantidade_To EndIf If not (&TFlanestItemValidade.IsEmpty() AND &TFlanestItemValidade_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Validade") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Date = &TFlanestItemValidade WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Date = &TFlanestItemValidade_To EndIf If not (&TFlanestItemObservacao_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Observação") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFlanestItemObservacao_Sel) Else If not (&TFlanestItemObservacao.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Observação") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFlanestItemObservacao) EndIf EndIf If not (&TFlanestItemLocDescricao_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Unidade") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFlanestItemLocDescricao_Sel) Else If not (&TFlanestItemLocDescricao.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Unidade") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFlanestItemLocDescricao) EndIf EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnslancarestoqueUEitemWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnslancarestoqueUEitemWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnslancarestoqueUEitem order lanestItemCadastro lanestItemLocCodigo lanestItemProdDescricao when &OrderedBy = 1 order prefCodigo lanestcodigo lanestItemProdCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (prefCodigo) (lanestcodigo) (lanestItemProdCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo lanestcodigo lanestItemProdDescricao when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) (lanestcodigo) (lanestItemProdDescricao) when &OrderedBy = 3 AND &OrderedDsc = True order prefCodigo lanestcodigo lanestItemProdUni when &OrderedBy = 4 AND &OrderedDsc = False order (prefCodigo) (lanestcodigo) (lanestItemProdUni) when &OrderedBy = 4 AND &OrderedDsc = True order prefCodigo lanestcodigo lanestItemQuantidade when &OrderedBy = 5 AND &OrderedDsc = False order (prefCodigo) (lanestcodigo) (lanestItemQuantidade) when &OrderedBy = 5 AND &OrderedDsc = True order prefCodigo lanestcodigo lanestItemValidade when &OrderedBy = 6 AND &OrderedDsc = False order (prefCodigo) (lanestcodigo) (lanestItemValidade) when &OrderedBy = 6 AND &OrderedDsc = True order prefCodigo lanestcodigo lanestItemObservacao when &OrderedBy = 7 AND &OrderedDsc = False order (prefCodigo) (lanestcodigo) (lanestItemObservacao) when &OrderedBy = 7 AND &OrderedDsc = True
using trnslancarestoqueUEitemWWDS(&prefCodigo, &lanestcodigo, &DynamicFiltersSelector1, &DynamicFiltersOperator1, &lanestItemLocDescricao1, &lanestItemProdDescricao1 , &lanestItemProdCodigo1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &lanestItemLocDescricao2, &lanestItemProdDescricao2 , &lanestItemProdCodigo2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &lanestItemLocDescricao3, &lanestItemProdDescricao3 , &lanestItemProdCodigo3, &TFlanestItemProdCodigo, &TFlanestItemProdCodigo_To, &TFlanestItemProdDescricao, &TFlanestItemProdDescricao_Sel, &TFlanestItemProdUni , &TFlanestItemProdUni_To, &TFlanestItemQuantidade, &TFlanestItemQuantidade_To, &TFlanestItemValidade, &TFlanestItemValidade_To, &TFlanestItemObservacao , &TFlanestItemObservacao_Sel, &TFlanestItemLocDescricao, &TFlanestItemLocDescricao_Sel) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'lanestItemProdCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = lanestItemProdCodigo Case &ColumnsSelector_Column.ColumnName = !'lanestItemProdDescricao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(lanestItemProdDescricao) Case &ColumnsSelector_Column.ColumnName = !'lanestItemProdUni' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = lanestItemProdUni Case &ColumnsSelector_Column.ColumnName = !'lanestItemQuantidade' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = lanestItemQuantidade Case &ColumnsSelector_Column.ColumnName = !'lanestItemValidade' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Date = lanestItemValidade Case &ColumnsSelector_Column.ColumnName = !'lanestItemObservacao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(lanestItemObservacao) Case &ColumnsSelector_Column.ColumnName = !'lanestItemLocDescricao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(lanestItemLocDescricao) EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnslancarestoqueUEitemWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"lanestItemProdCodigo", '', !'Codigo', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"lanestItemProdDescricao", '', !'Descrição', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"lanestItemProdUni", '', !'Unidade', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"lanestItemQuantidade", '', !'Quantidade', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"lanestItemValidade", '', !'Validade', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"lanestItemObservacao", '', !'Observação', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"lanestItemLocDescricao", '', !'Unidade', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnslancarestoqueUEitemWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnslancarestoqueUEitemWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnslancarestoqueUEitemWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnslancarestoqueUEitemWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFLANESTITEMPRODCODIGO" &TFlanestItemProdCodigo.FromString(&GridStateFilterValue.Value) &TFlanestItemProdCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFLANESTITEMPRODDESCRICAO" &TFlanestItemProdDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLANESTITEMPRODDESCRICAO_SEL" &TFlanestItemProdDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLANESTITEMPRODUNI" &TFlanestItemProdUni.FromString(&GridStateFilterValue.Value) &TFlanestItemProdUni_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFLANESTITEMQUANTIDADE" &TFlanestItemQuantidade.FromString(&GridStateFilterValue.Value) &TFlanestItemQuantidade_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFLANESTITEMVALIDADE" &TFlanestItemValidade.FromString(&GridStateFilterValue.Value) &TFlanestItemValidade_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFLANESTITEMOBSERVACAO" &TFlanestItemObservacao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLANESTITEMOBSERVACAO_SEL" &TFlanestItemObservacao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLANESTITEMLOCDESCRICAO" &TFlanestItemLocDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFLANESTITEMLOCDESCRICAO_SEL" &TFlanestItemLocDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&PREFCODIGO" &prefCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&LANESTCODIGO" &lanestcodigo.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
